WITH base AS (SELECT *, LOWER(txn_type) AS txn_type_lower FROM transactions WHERE merchant IS NOT NULL), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY txn_time ASC NULLS FIRST, id ASC) AS dedup_rank FROM base) t WHERE dedup_rank = 1), with_dims AS (SELECT src.*, d.opened_date, d.account_type FROM ranked src LEFT JOIN accounts d ON src.account_id = d.id), prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY account_type ORDER BY txn_time ASC, id ASC) AS prev_txn_time FROM with_dims), gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM prev_events), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY account_type ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps), with_gaps AS (SELECT *, CASE WHEN LAG(prev_txn_time) OVER (PARTITION BY merchant ORDER BY prev_txn_time ASC, id ASC) IS NULL OR prev_txn_time > LAG(prev_txn_time) OVER (PARTITION BY merchant ORDER BY prev_txn_time ASC, id ASC) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM sessions_transactions), sessions_transactions_2 AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY merchant ORDER BY prev_txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps), scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_type ORDER BY session_id DESC, id ASC) AS seq_no, FIRST_VALUE(session_start_flag) IGNORE NULLS OVER (PARTITION BY txn_type ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_session_start_flag, LAG(session_id, 2) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) AS prev_session_id, CUME_DIST() OVER (ORDER BY island_id ASC) AS island_id_cume_dist, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY txn_time DESC, id ASC) AS seq_no_2 FROM sessions_transactions_2 WHERE merchant IN ('Lazada', 'Starbucks', '7-Eleven')), enriched AS (SELECT e.id, e.account_id, e.amount, e.txn_type_lower, e.opened_date, e.prev_txn_time, e.session_start_flag, e.new_group_flag, e.seq_no, e.first_known_session_start_flag, p.opened_date AS account_opened_date, p.balance, p.status FROM scored e LEFT JOIN accounts p ON e.account_id = p.id) SELECT id, account_id, amount, txn_type_lower, prev_txn_time, session_start_flag, new_group_flag, first_known_session_start_flag, account_opened_date FROM enriched ORDER BY id DESC NULLS LAST
